const data = $input.first().json;
const step1 = $('01 XML 결과 정규화').first().json;
const timestamp = new Date().toLocaleString('ko-KR', { timeZone: 'Asia/Seoul' });
const formatCount = (value) => Number.isInteger(value) && value >= 0 ? `${value}건` : '확인 불가';
const globalCmCount = step1.globalCmLeaderApprovalCommentCheckStatus === 'checked'
  ? formatCount(step1.globalCmLeaderApprovalCommentMissingCount)
  : '확인 불가';
return [{ json: {
  calendarStatus: 'success',
  exitCode: data.exitCode,
  title: '✅ 팀 배포 캘린더 현황 자동화 완료',
  message: `✅ 팀 배포 캘린더 현황 자동화 완료

실행 완료: ${timestamp}

[수행 단계]
1. XML 생성
2. HTML 미리보기 생성
3. Confluence 업로드

[점검 결과]
- 배포완료 미확인: ${formatCount(step1.deploymentCompletionUnconfirmedCount)}
- 승인일 미기재: ${formatCount(step1.approvalDateMissingCount)}
- GlobalCM 팀장 승인 댓글 없음: ${globalCmCount}

[업로드 결과]
${data.message}`,
} }];

const data = $input.first().json;
const timestamp = new Date().toLocaleString('ko-KR', { timeZone: 'Asia/Seoul' });
const stdout = String(data.stdout || '').substring(0, 600);
const stderr = String(data.stderr || '').substring(0, 600);
return [{ json: {
  calendarStatus: 'failed',
  exitCode: data.exitCode,
  title: '⚠️ 팀 배포 캘린더 현황 자동화 오류',
  message: `⚠️ 팀 배포 캘린더 현황 자동화 오류

오류 발생: ${timestamp}
단계: ${data.stageLabel || data.stage}
종료 코드: ${data.exitCode}
메시지: ${data.message}

[표준 출력]
${stdout}

[오류 출력]
${stderr}`,
} }];

const data = $input.first().json;
let commandOutput = {};
try {
  commandOutput = $('01 XML 생성').first().json || {};
} catch (_) {}

const result = data.step1Result;
const fallbackExitCode = Number(commandOutput.exitCode ?? data.exitCode ?? commandOutput.error?.exitCode ?? 99);
const normalizedFallbackExitCode = Number.isInteger(fallbackExitCode) ? fallbackExitCode : 99;
const unavailable = {
  calendarStatus: 'failed',
  step: '1',
  stage: 'xml',
  stageLabel: 'XML 생성',
  exitCode: normalizedFallbackExitCode === 0 ? 99 : normalizedFallbackExitCode,
  message: `XML 생성 결과 파일을 읽거나 해석하지 못했습니다.${data.error ? ` ${String(data.error)}` : ''}`,
  details: {},
  warnings: [],
  stdout: commandOutput.stdout ?? '',
  stderr: commandOutput.stderr ?? commandOutput.error?.message ?? data.error ?? '',
  calendarResult: null,
  deploymentCompletionUnconfirmedCount: null,
  approvalDateMissingCount: null,
  globalCmLeaderApprovalCommentMissingCount: null,
  globalCmLeaderApprovalCommentCheckStatus: 'unavailable',
};

if (!result || typeof result !== 'object' || Array.isArray(result)) {
  return [{ json: unavailable }];
}

const details = result.details && typeof result.details === 'object' && !Array.isArray(result.details)
  ? result.details
  : {};
const countOrNull = (value) => Number.isInteger(value) && value >= 0 ? value : null;
const deploymentCompletionUnconfirmedCount = countOrNull(details.deploymentCompletionUnconfirmedCount);
const approvalDateMissingCount = countOrNull(details.approvalDateMissingCount);
const globalCmLeaderApprovalCommentCheckStatus =
  details.globalCmLeaderApprovalCommentCheckStatus === 'checked' ? 'checked' : 'unavailable';
const globalCmLeaderApprovalCommentMissingCount =
  globalCmLeaderApprovalCommentCheckStatus === 'checked'
    ? countOrNull(details.globalCmLeaderApprovalCommentMissingCount)
    : null;
const rawExitCode = Number(result.exitCode);
const exitCode = Number.isInteger(rawExitCode) ? rawExitCode : 99;
const resultIsSuccessful = result.status === 'success' && exitCode === 0;
if (
  resultIsSuccessful &&
  (
    deploymentCompletionUnconfirmedCount === null ||
    approvalDateMissingCount === null ||
    (
      globalCmLeaderApprovalCommentCheckStatus === 'checked' &&
      globalCmLeaderApprovalCommentMissingCount === null
    )
  )
) {
  return [{ json: {
    ...unavailable,
    message: 'XML 생성 결과에 필수 점검 건수가 없습니다.',
    calendarResult: result,
    details,
    warnings: Array.isArray(result.warnings) ? result.warnings : [],
  } }];
}

return [{ json: {
  calendarStatus: result.status === 'success' && exitCode === 0 ? 'success' : 'failed',
  step: result.step ?? '1',
  stage: result.stage ?? 'xml',
  stageLabel: result.stageLabel ?? 'XML 생성',
  exitCode,
  message: result.message ?? (exitCode === 0 ? 'XML 생성이 정상 완료되었습니다.' : 'XML 생성이 실패했습니다.'),
  details,
  warnings: Array.isArray(result.warnings) ? result.warnings : [],
  stdout: commandOutput.stdout ?? '',
  stderr: commandOutput.stderr ?? commandOutput.error?.message ?? '',
  calendarResult: result,
  deploymentCompletionUnconfirmedCount,
  approvalDateMissingCount,
  globalCmLeaderApprovalCommentMissingCount,
  globalCmLeaderApprovalCommentCheckStatus,
} }];

const data = $input.first().json;
const marker = 'CALENDAR_RESULT=';
let result = null;
for (const stream of [data.stdout, data.stderr, data.error?.message, data.message].filter(Boolean)) {
  const text = String(stream);
  const index = text.lastIndexOf(marker);
  if (index >= 0) {
    const candidate = text.slice(index + marker.length).split(/\r?\n/)[0].trim();
    try { result = JSON.parse(candidate); } catch (_) {}
  }
}
const rawExitCode = result?.exitCode ?? data.exitCode ?? data.error?.exitCode ?? 99;
const exitCode = Number(rawExitCode);
const normalizedExitCode = Number.isInteger(exitCode) ? exitCode : 99;
const fallbackMessage = normalizedExitCode === 0 ? 'HTML 미리보기 생성이 정상 완료되었습니다. (n8n 종료 코드 0)' : 'HTML 생성 결과를 해석하지 못했습니다.';
return [{ json: {
  calendarStatus: result?.status ?? (normalizedExitCode === 0 ? 'success' : 'failed'),
  step: result?.step ?? '2',
  stage: result?.stage ?? 'html',
  stageLabel: result?.stageLabel ?? 'HTML 미리보기 생성',
  exitCode: normalizedExitCode,
  message: result?.message ?? data.error?.message ?? data.message ?? fallbackMessage,
  details: result?.details ?? {},
  warnings: result?.warnings ?? [],
  stdout: data.stdout ?? '',
  stderr: data.stderr ?? data.error?.message ?? '',
  calendarResult: result,
} }];

const data = $input.first().json;
const marker = 'CALENDAR_RESULT=';
let result = null;
for (const stream of [data.stdout, data.stderr, data.error?.message, data.message].filter(Boolean)) {
  const text = String(stream);
  const index = text.lastIndexOf(marker);
  if (index >= 0) {
    const candidate = text.slice(index + marker.length).split(/\r?\n/)[0].trim();
    try { result = JSON.parse(candidate); } catch (_) {}
  }
}
const rawExitCode = result?.exitCode ?? data.exitCode ?? data.error?.exitCode ?? 99;
const exitCode = Number(rawExitCode);
const normalizedExitCode = Number.isInteger(exitCode) ? exitCode : 99;
const fallbackMessage = normalizedExitCode === 0 ? 'Confluence 업로드가 정상 완료되었습니다. (n8n 종료 코드 0)' : 'Confluence 업로드 결과를 해석하지 못했습니다.';
return [{ json: {
  calendarStatus: result?.status ?? (normalizedExitCode === 0 ? 'success' : 'failed'),
  step: result?.step ?? '3',
  stage: result?.stage ?? 'upload',
  stageLabel: result?.stageLabel ?? 'Confluence 업로드',
  exitCode: normalizedExitCode,
  message: result?.message ?? data.error?.message ?? data.message ?? fallbackMessage,
  details: result?.details ?? {},
  warnings: result?.warnings ?? [],
  stdout: data.stdout ?? '',
  stderr: data.stderr ?? data.error?.message ?? '',
  calendarResult: result,
} }];
